161	export const uploadImagem = async (file, folder = 'geral') => {
162	  const sessionResult = await supabase.auth.getSession().catch(() => ({ data: {} }));
163	  const token = sessionResult?.data?.session?.access_token;
164	  if (!token) throw new Error('Sessão expirada. Faça login novamente.');
165	
166	  const form = new FormData();
167	  form.append('file', file);
168	
169	  const res = await fetch(`${apiPath('/api/restaurante')}/storage/upload?folder=${encodeURIComponent(folder)}`, {
170	    method: 'POST',
171	    headers: { Authorization: `Bearer ${token}` },
172	    body: form,
173	  });
174	
175	  const contentType = res.headers.get('content-type') ?? '';
176	  const json = contentType.includes('application/json') ? await res.json().catch(() => ({})) : {};
177	  if (!res.ok) throw new Error(json?.message ?? `HTTP ${res.status}`);
178	  return json; // { url: string }
179	};
