export const bloquearMesaSalao = (id) => apiFetch(`/salao/mesas/${id}/bloquear`, { method: 'PATCH' });
export const desbloquearMesaSalao = (id) => apiFetch(`/salao/mesas/${id}/desbloquear`, { method: 'PATCH' });
export const getSalaoComandas = () => apiFetch('/salao/comandas');
export const getSalaoComandasFechadasHoje = () => apiFetch('/salao/comandas/fechadas-hoje');
export const abrirComandaSalao = ({ mesa_id, cliente_nome, cliente_telefone }) =>
  apiFetch('/salao/comandas/abrir', { method: 'POST', body: JSON.stringify({ mesa_id: mesa_id ?? null, cliente_nome, cliente_telefone }) });
export const venderDireto = (itens, forma_pagamento, valor_recebido) =>
  apiFetch('/salao/venda-direta', { method: 'POST', body: JSON.stringify({ itens, forma_pagamento, valor_recebido }) });
export const getSalaoComandaDetalhe = (id) => apiFetch(`/salao/comandas/${id}`);
export const aplicarDescontoComanda = (id, valor) =>
  apiFetch(`/salao/comandas/${id}/desconto`, { method: 'PATCH', body: JSON.stringify({ valor }) });
export const aplicarAcrescimoComanda = (id, valor) =>
  apiFetch(`/salao/comandas/${id}/acrescimo`, { method: 'PATCH', body: JSON.stringify({ valor }) });
export const cancelarComandaSalao = (id) =>
  apiFetch(`/salao/comandas/${id}/cancelar`, { method: 'POST' });
export const reabrirComandaSalao = (id) =>
  apiFetch(`/salao/comandas/${id}/reabrir`, { method: 'POST' });
export const imprimirConferenciaSalao = (id, valores) =>
  apiFetch(`/salao/comandas/${id}/imprimir-conferencia`, { method: 'POST', body: JSON.stringify(valores ?? {}) });
export const reimprimirReciboSalao = (id) =>
  apiFetch(`/salao/comandas/${id}/reimprimir-recibo`, { method: 'POST' });
export const pagarComandaSalao = (id, forma_pagamento, gorjeta_valor, valor_recebido) =>
  apiFetch(`/salao/comandas/${id}/pagar`, { method: 'POST', body: JSON.stringify({ forma_pagamento, gorjeta_valor, valor_recebido }) });
export const adicionarItensComandaSalao = (id, itens) =>
  apiFetch(`/salao/comandas/${id}/itens`, { method: 'POST', body: JSON.stringify({ itens }) });
export const editarItemComandaSalao = (id, itemId, body) =>
  apiFetch(`/salao/comandas/${id}/itens/${itemId}`, { method: 'PATCH', body: JSON.stringify(body) });
export const removerItemComandaSalao = (id, itemId) =>
  apiFetch(`/salao/comandas/${id}/itens/${itemId}`, { method: 'DELETE' });
export const transferirGarcomComanda = (id, garcom_id) =>
  apiFetch(`/salao/comandas/${id}/transferir-garcom`, { method: 'PATCH', body: JSON.stringify({ garcom_id }) });
export const registrarPagamentoParcialSalao = (id, valor, forma_pagamento, valor_recebido) =>
  apiFetch(`/salao/comandas/${id}/pagamento`, { method: 'POST', body: JSON.stringify({ valor, forma_pagamento, valor_recebido }) });
export const editarPagamentoParcialSalao = (id, pagamentoId, valor, forma_pagamento) =>
  apiFetch(`/salao/comandas/${id}/pagamentos/${pagamentoId}`, { method: 'PATCH', body: JSON.stringify({ valor, forma_pagamento }) });
export const removerPagamentoParcialSalao = (id, pagamentoId) =>
  apiFetch(`/salao/comandas/${id}/pagamentos/${pagamentoId}`, { method: 'DELETE' });
export const transferirComandaSalao = (id, { mesa_id, comanda_destino_id }) =>
  apiFetch(`/salao/comandas/${id}/transferir`, { method: 'PATCH', body: JSON.stringify({ mesa_id, comanda_destino_id }) });
export const getSugestaoGorjeta = (id) => apiFetch(`/salao/comandas/${id}/sugestao-gorjeta`);

// Módulo Salão — mesas (CRUD simples pelo dono, cadastro inicial das mesas físicas)
export const listarMesas = () => apiFetch('/mesas-cadastro');
export const criarMesa = (data) =>
  apiFetch('/mesas-cadastro', { method: 'POST', body: JSON.stringify(data) });
export const removerMesa = (id) =>
  apiFetch(`/mesas-cadastro/${id}`, { method: 'DELETE' });
export const criarMesasEmLote = (de, ate) =>
  apiFetch('/mesas-cadastro/lote', { method: 'POST', body: JSON.stringify({ de, ate }) });

